// Editor diagnostic only. Parent may stage this under Assets/.../Editor and invoke in PlayMode.
using System;using System.Collections.Generic;using System.IO;using System.Linq;using TMPro;using UnityEditor;using UnityEngine;using UnityEngine.Sprites;using UnityEngine.UI;
public static class UiGeometrySnapshot {
 [Serializable] public class Report{public int screenWidth,screenHeight;public string defaultSettingsPath,defaultSettingsGuid,defaultSpriteName,defaultSpritePath;public List<ImageInfo> images=new List<ImageInfo>();public List<TextInfo> texts=new List<TextInfo>();public List<LayoutInfo> layouts=new List<LayoutInfo>();}
 [Serializable] public class ImageInfo{public string path,sprite,spritePath,spriteGuid,texture,canvas;public int type,textureWidth,textureHeight;public bool preserveAspect,useSpriteMesh;public Vector2 rectSize,sizeDelta,anchorMin,anchorMax,pivot,spritePivot;public Rect spriteRect;public Vector3 localScale,lossyScale;public Vector4 spritePadding,spriteBorder,outerUV,screenRect;public float imagePixelsPerUnit,pixelsPerUnitMultiplier,spritePixelsPerUnit,canvasScale,canvasReferencePixelsPerUnit;public Vector3 meshBoundsCenter,meshBoundsSize;public int meshVertices;}
 [Serializable] public class TextInfo{public string path,text,serializedOrResolvedSpriteAsset;public float fontSize;public List<SpriteCharacter> spriteCharacters=new List<SpriteCharacter>();}
 [Serializable] public class SpriteCharacter{public int characterIndex,spriteIndex;public string asset,glyphName;public uint glyphIndex;public float scale,xAdvance;public Vector3 bottomLeft,topRight;}
 [Serializable] public class LayoutInfo{public string path,type;public bool enabled;public int childCount,activeChildCount,layoutChildCount;public Vector2 cellSize,spacing;public int constraint,constraintCount;public Rect rect;public Vector3 localScale,lossyScale;}
 static string PathOf(Transform t){string p=t.name;while(t.parent!=null){t=t.parent;p=t.name+"/"+p;}return p;}
 static Vector4 ScreenRect(RectTransform t,Canvas c){var corners=new Vector3[4];t.GetWorldCorners(corners);Camera camera=c==null||c.renderMode==RenderMode.ScreenSpaceOverlay?null:c.worldCamera;var p=corners.Select(x=>RectTransformUtility.WorldToScreenPoint(camera,x)).ToArray();return new Vector4(p.Min(x=>x.x),p.Min(x=>x.y),p.Max(x=>x.x)-p.Min(x=>x.x),p.Max(x=>x.y)-p.Min(x=>x.y));}
 public static void Write(string path){
  Canvas.ForceUpdateCanvases();var r=new Report{screenWidth=Screen.width,screenHeight=Screen.height};var settings=Resources.Load<TMP_Settings>("TMP Settings");r.defaultSettingsPath=AssetDatabase.GetAssetPath(settings);r.defaultSettingsGuid=AssetDatabase.AssetPathToGUID(r.defaultSettingsPath);var defaultSprite=TMP_Settings.defaultSpriteAsset;r.defaultSpriteName=defaultSprite==null?"null":defaultSprite.name;r.defaultSpritePath=AssetDatabase.GetAssetPath(defaultSprite);
  foreach(var image in UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Image>(FindObjectsSortMode.None)){
   if(!image.enabled||!image.gameObject.activeInHierarchy)continue;var t=image.rectTransform;var s=image.overrideSprite??image.sprite;var c=image.canvas;var m=image.canvasRenderer.GetMesh();
   var v=new ImageInfo{path=PathOf(t),type=(int)image.type,preserveAspect=image.preserveAspect,useSpriteMesh=image.useSpriteMesh,rectSize=t.rect.size,sizeDelta=t.sizeDelta,anchorMin=t.anchorMin,anchorMax=t.anchorMax,pivot=t.pivot,localScale=t.localScale,lossyScale=t.lossyScale,imagePixelsPerUnit=image.pixelsPerUnit,pixelsPerUnitMultiplier=image.pixelsPerUnitMultiplier,canvas=c==null?"null":PathOf(c.transform),canvasScale=c==null?0:c.scaleFactor,canvasReferencePixelsPerUnit=c==null?0:c.referencePixelsPerUnit,screenRect=ScreenRect(t,c),meshBoundsCenter=m==null?Vector3.zero:m.bounds.center,meshBoundsSize=m==null?Vector3.zero:m.bounds.size,meshVertices=m==null?0:m.vertexCount};
   if(s!=null){v.sprite=s.name;v.spritePath=AssetDatabase.GetAssetPath(s);v.spriteGuid=AssetDatabase.AssetPathToGUID(v.spritePath);v.spriteRect=s.rect;v.spritePivot=s.pivot;v.spritePixelsPerUnit=s.pixelsPerUnit;v.spriteBorder=s.border;v.spritePadding=DataUtility.GetPadding(s);v.outerUV=DataUtility.GetOuterUV(s);v.texture=s.texture.name;v.textureWidth=s.texture.width;v.textureHeight=s.texture.height;}
   r.images.Add(v);
  }
  foreach(var text in UnityEngine.Object.FindObjectsByType<TextMeshProUGUI>(FindObjectsSortMode.None)){
   if(!text.enabled||!text.gameObject.activeInHierarchy)continue;var info=new TextInfo{path=PathOf(text.transform),text=text.text,fontSize=text.fontSize,serializedOrResolvedSpriteAsset=text.spriteAsset==null?"null":AssetDatabase.GetAssetPath(text.spriteAsset)};
   if(text.textInfo!=null)for(int i=0;i<text.textInfo.characterCount;i++){var ch=text.textInfo.characterInfo[i];if(ch.elementType!=TMP_TextElementType.Sprite)continue;var sc=ch.textElement as TMP_SpriteCharacter;var asset=sc==null?null:sc.textAsset as TMP_SpriteAsset;info.spriteCharacters.Add(new SpriteCharacter{characterIndex=i,spriteIndex=asset==null?-1:asset.spriteCharacterTable.IndexOf(sc),asset=asset==null?"null":AssetDatabase.GetAssetPath(asset),glyphName=sc==null?"null":sc.name,glyphIndex=sc==null?uint.MaxValue:sc.glyphIndex,scale=ch.scale,xAdvance=ch.xAdvance,bottomLeft=ch.bottomLeft,topRight=ch.topRight});}r.texts.Add(info);
  }
  foreach(var g in UnityEngine.Object.FindObjectsByType<LayoutGroup>(FindObjectsSortMode.None)){
   if(!g.gameObject.activeInHierarchy)continue;var t=(RectTransform)g.transform;var d=new LayoutInfo{path=PathOf(t),type=g.GetType().Name,enabled=g.enabled,childCount=t.childCount,activeChildCount=Enumerable.Range(0,t.childCount).Count(i=>t.GetChild(i).gameObject.activeInHierarchy),rect=t.rect,localScale=t.localScale,lossyScale=t.lossyScale};
   d.layoutChildCount=Enumerable.Range(0,t.childCount).Select(i=>t.GetChild(i)).Count(child=>child.gameObject.activeInHierarchy&&!child.GetComponents<Component>().OfType<ILayoutIgnorer>().Any(x=>x.ignoreLayout));if(g is GridLayoutGroup grid){d.cellSize=grid.cellSize;d.spacing=grid.spacing;d.constraint=(int)grid.constraint;d.constraintCount=grid.constraintCount;}else if(g is HorizontalOrVerticalLayoutGroup h)d.spacing=new Vector2(h.spacing,h.spacing);r.layouts.Add(d);
  }
  Directory.CreateDirectory(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path)));File.WriteAllText(path,JsonUtility.ToJson(r,true));
 }
}
